# 1. On your desktop machine, prepare your Android device for remote debugging:
adb kill-server
adb start-server
adb devices
# (make sure your Moto device appears and USB debugging is enabled)
adb forward tcp:9222 localabstract:chrome_devtools_remote

# 2. Run Lighthouse CLI against the device forwarding port
lighthouse https://example.com \
  --port=9222 \
  --screenEmulation.disabled \
  --no-emulatedUserAgent \
  --throttling-method=devtools \
  --throttling.cpuSlowdownMultiplier=1 \
  --output=html \
  --output-path=lh-on-device.html

# 3. Open the generated report
open lh-on-device.html

# (Alternatively, programmatic reproduction via Node.js)

// reproduce-lh-device.js
const fs = require('fs');
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
(async () => {
  // Launch a local headless chrome -- not used when port is provided,
  // but shown here for completeness if you wanted to script port forwarding.
  // We skip chromeLauncher.launch() since the remote device is providing it.

  // Run Lighthouse against the URL over the forwarded port
  const options = {
    port: 9222,
    screenEmulation: {disabled: true},
    emulatedUserAgent: false,
    throttlingMethod: 'devtools',
    throttling: {cpuSlowdownMultiplier: 1},
    output: 'html',
    logLevel: 'info',
  };
  const runnerResult = await lighthouse('https://example.com', options);

  // Write the report to disk
  fs.writeFileSync('lh-on-device-node.html', runnerResult.report);
  console.log('Report written to lh-on-device-node.html');
})();
